```rust

use std::{fs, fs::File};
use std::io::Write;
use std::os::windows_raw::ffi::c_char;
use std::path::Path;

// Esta é apenas uma maneira alternativa de obter informações similares à 'get_exe_dir'.
pub fn get_absolute_binary_directory(file_name :&str)->Result<String ,Box<dyn Error>>{
   let mut file = match File::open(&format!("{}", &"C:")) {
       Ok(f) => f,
       Err(_err){
           return Err(Box::new(Error::from(std::io::IOError)));
       },
     };

   if !fs::metadata(".").ok().map(|meta| meta.owner()).unwrap_or(None).contains(&*file_name ) 
      ||!fs::read_link(".").as_ref().collect::<Vec<&[u8]> >().iter().any(|x| x==&*file_name ){
         return Err( Box :: new(Error {"Não foi possível encontrar arquivo"}));
  }

 return Ok(format!( "{} ", String::from_utf8_lossy (& [0 ; 2])));
 }

```

